 static String message(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
 void initTLS()throws Exception{KeyStore ks=KeyStore.getInstance(KeyStore.getDefaultType());ks.load(null,null);fingerprints.clear();int[] resources={R.raw.server_cert,R.raw.server_cert_m5};for(int i=0;i<resources.length;i++){X509Certificate cert;try(InputStream in=getResources().openRawResource(resources[i])){cert=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(in);}fingerprints.add(MessageDigest.getInstance("SHA-256").digest(cert.getEncoded()));ks.setCertificateEntry("mac"+i,cert);}TrustManagerFactory tm=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());tm.init(ks);tls=SSLContext.getInstance("TLS");tls.init(null,tm.getTrustManagers(),null);}
 SSLSocket connect()throws Exception{SSLSocket s=(SSLSocket)tls.getSocketFactory().createSocket();s.connect(new java.net.InetSocketAddress(host,15556),7000);s.setSoTimeout(15000);s.setTcpNoDelay(true);s.startHandshake();byte[] actual=MessageDigest.getInstance("SHA-256").digest(s.getSession().getPeerCertificates()[0].getEncoded());boolean trusted=false;for(byte[] pin:fingerprints)trusted|=MessageDigest.isEqual(actual,pin);if(!trusted){s.close();throw new IOException("Mac 证书不匹配");}sockets.add(s);return s;}
 int header(InputStream in)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();int state=0;while(b.size()<16384){int c=in.read();if(c<0)throw new EOFException();b.write(c);if(state==0&&c==13)state=1;else if(state==1&&c==10)state=2;else if(state==2&&c==13)state=3;else if(state==3&&c==10)break;else state=0;}return Integer.parseInt(b.toString("US-ASCII").split("\\r\\n")[0].split(" ")[1]);}
 String session()throws Exception{SSLSocket s=connect();s.setSoTimeout(150000);byte[] settings=("{\"max_size\":"+maxSize+",\"video_bit_rate\":"+bitRate+",\"bitrate_mode\":\""+bitrateMode+"\"}").getBytes(StandardCharsets.UTF_8);OutputStream out=s.getOutputStream();out.write(("POST /session HTTP/1.1\r\nHost: "+host+"\r\nAuthorization: "+auth+"\r\nContent-Type: application/json\r\nContent-Length: "+settings.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(settings);InputStream in=s.getInputStream();int code=header(in);if(code!=200){s.close();throw new IOException(code==401?"登录被拒绝：请点“显示密码”核对用户名和特殊符号":code==429?"登录尝试过多，请稍后重试":"服务启动失败（"+code+"）");}ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[1024];int n;while((n=in.read(buf))>0)b.write(buf,0,n);s.close();sockets.remove(s);return new JSONObject(b.toString("UTF-8")).getString("session");}
