 void fit(){if(canvas==null)return;int w=canvas.getWidth(),h=canvas.getHeight();if(w==0||h==0)return;float s=Math.min((float)w/width,(float)h/height);screen.setLayoutParams(new FrameLayout.LayoutParams(Math.round(width*s),Math.round(height*s),17));}
 void configure(int w,int h,int gen)throws Exception{width=w;height=h;runOnUiThread(this::fit);for(int i=0;i<100&&running&&!screen.getHolder().getSurface().isValid();i++)Thread.sleep(20);MediaCodec old=video;video=null;if(old!=null){old.stop();old.release();}MediaFormat f=MediaFormat.createVideoFormat("video/avc",w,h);f.setInteger(MediaFormat.KEY_LOW_LATENCY,1);MediaCodec d=fastDecoder(f);Surface surface=screen.getHolder().getSurface();try{surface.setFrameRate(60,Surface.FRAME_RATE_COMPATIBILITY_FIXED_SOURCE);}catch(IllegalStateException ignored){}d.configure(f,surface,null,0);d.start();video=d;d.setOnFrameRenderedListener((codec,pts,ns)->{if(running&&gen==generation&&video==d)presentedFrames.incrementAndGet();},new Handler(statsThread.getLooper()));PlaybackClock clock=playback;new Thread(()->{MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();try{while(running&&gen==generation&&video==d){int index=d.dequeueOutputBuffer(info,10000);if(index>=0){long target=clock.deadline(info.presentationTimeUs);if(target<System.nanoTime()-40000000L){d.releaseOutputBuffer(index,false);continue;}while(running&&gen==generation&&video==d&&target-System.nanoTime()>20000000L)Thread.sleep(2);if(!running||gen!=generation||video!=d)break;d.releaseOutputBuffer(index,Math.max(System.nanoTime(),target));}}}catch(Exception e){if(running&&gen==generation&&video==d)fail(e);}},"video-render").start();}
 void readVideo(SSLSocket s,int gen)throws Exception{DataInputStream in=new DataInputStream(new BufferedInputStream(s.getInputStream(),65536));if(in.readInt()!=0x68323634)throw new IOException("不支持的视频编码");while(running&&gen==generation){int hi=in.readInt();if((hi&0x80000000)!=0){int w=in.readInt(),h=in.readInt();if(w<1||h<1||w>8192||h>8192)throw new IOException("无效画面尺寸");configure(w,h,gen);continue;}long pts=((long)hi<<32)|(in.readInt()&0xffffffffL);int size=in.readInt();if(size<0||size>8*1024*1024)throw new IOException("无效视频帧");byte[] b=new byte[size];in.readFully(b);if((pts&(1L<<62))==0){receivedFrames.incrementAndGet();playback.observe(pts&((1L<<61)-1),System.nanoTime());}MediaCodec d=video;if(d==null)throw new IOException("缺少画面尺寸");int index=-1;while(running&&gen==generation&&(index=d.dequeueInputBuffer(10000))<0){}if(index<0)break;ByteBuffer buffer=d.getInputBuffer(index);buffer.clear();buffer.put(b);d.queueInputBuffer(index,0,size,pts&((1L<<61)-1),(pts&(1L<<62))!=0?MediaCodec.BUFFER_FLAG_CODEC_CONFIG:0);}}
 void readAudio(SSLSocket s,int gen){try{DataInputStream in=new DataInputStream(new BufferedInputStream(s.getInputStream(),16384));int codec=in.readInt();if(codec==0||codec==1)return;if(codec!=0x00616163)throw new IOException("不支持的音频编码");while(running&&gen==generation){long pts=in.readLong();int size=in.readInt();if(size<0||size>1024*1024)throw new IOException("无效音频帧");byte[] data=new byte[size];in.readFully(data);if((pts&(1L<<62))!=0){MediaFormat f=MediaFormat.createAudioFormat("audio/mp4a-latm",48000,2);f.setByteBuffer("csd-0",ByteBuffer.wrap(data));MediaCodec d=MediaCodec.createDecoderByType("audio/mp4a-latm");d.configure(f,null,null,0);d.start();audio=d;int min=AudioTrack.getMinBufferSize(48000,12,2);track=new AudioTrack.Builder().setAudioFormat(new AudioFormat.Builder().setSampleRate(48000).setChannelMask(AudioFormat.CHANNEL_OUT_STEREO) .setEncoding(AudioFormat.ENCODING_PCM_16BIT).build()).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MOVIE).build()).setTransferMode(AudioTrack.MODE_STREAM).setBufferSizeInBytes(Math.max(min,4096)).setPerformanceMode(AudioTrack.PERFORMANCE_MODE_LOW_LATENCY).build();track.play();new Thread(()->drainAudio(d,gen),"audio-render").start();continue;}playback.observe(pts&((1L<<61)-1),System.nanoTime());MediaCodec d=audio;if(d==null)continue;int index=-1;while(running&&gen==generation&&(index=d.dequeueInputBuffer(10000))<0){}if(index<0)break;ByteBuffer buf=d.getInputBuffer(index);buf.clear();buf.put(data);d.queueInputBuffer(index,0,size,pts&((1L<<61)-1),0);}}catch(Exception e){if(running&&gen==generation)runOnUiThread(()->Toast.makeText(this,"音频暂不可用："+message(e),Toast.LENGTH_LONG).show());}}
 void drainAudio(MediaCodec d,int gen){AudioTrack output=track;PlaybackClock clock=playback;long writtenFrames=0;try{MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(running&&gen==generation&&audio==d){int index=d.dequeueOutputBuffer(info,10000);if(index>=0){ByteBuffer b=d.getOutputBuffer(index);b.position(info.offset);b.limit(info.offset+info.size);long target=clock.deadline(info.presentationTimeUs);while(running&&gen==generation&&audio==d){long queued=Math.max(0,writtenFrames-(output.getPlaybackHeadPosition()&0xffffffffL));long wait=target-System.nanoTime()-queued*1000000000L/48000;if(wait<=2000000L)break;Thread.sleep(Math.min(10,Math.max(1,wait/1000000L)));}while(b.hasRemaining()&&running&&gen==generation&&audio==d){int bytes=output.write(b,b.remaining(),AudioTrack.WRITE_BLOCKING);if(bytes<0)throw new IOException("音频输出失败");writtenFrames+=bytes/4;}d.releaseOutputBuffer(index,false);}}}catch(Exception ignored){}}
 void measureRtt(int gen){while(running&&gen==generation){SSLSocket socket=null;try{socket=connect();long start=System.nanoTime();socket.getOutputStream().write(("GET /ping HTTP/1.1\r\nHost: "+host+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));if(header(socket.getInputStream())==200&&running&&gen==generation)networkRttMs=Math.max(1,(System.nanoTime()-start)/1000000L);else networkRttMs=-1;}catch(Exception ignored){if(gen==generation)networkRttMs=-1;}finally{if(socket!=null){sockets.remove(socket);try{socket.close();}catch(Exception ignored){}}}try{Thread.sleep(3000);}catch(InterruptedException e){return;}}}
 synchronized void touch(MotionEvent e){if(control==null||!running)return;try{int a=e.getActionMasked();if(a==2){for(int i=0;i<e.getPointerCount();i++)pointer(e,i,2);}else if(a==0||a==5)pointer(e,e.getActionIndex(),0);else if(a==1||a==6)pointer(e,e.getActionIndex(),1);else if(a==3){for(int i=0;i<e.getPointerCount();i++)pointer(e,i,1);}control.flush();}catch(Exception ex){fail(ex);}}
 void pointer(MotionEvent e,int i,int a)throws IOException{int x=Math.max(0,Math.min(width-1,Math.round(e.getX(i)*width/screen.getWidth()))),y=Math.max(0,Math.min(height-1,Math.round(e.getY(i)*height/screen.getHeight())));control.writeByte(2);control.writeByte(a);control.writeLong(e.getPointerId(i));control.writeInt(x);control.writeInt(y);control.writeShort(width);control.writeShort(height);control.writeShort(a==1?0:65535);control.writeInt(0);control.writeInt(0);}
 synchronized void key(int code){if(control==null)return;try{for(int a=0;a<2;a++){control.writeByte(0);control.writeByte(a);control.writeInt(code);control.writeInt(0);control.writeInt(0);}control.flush();}catch(Exception e){fail(e);}}
 void fail(Exception e){runOnUiThread(()->{if(!running)return;stop();login();status.setText("连接中断："+message(e));});}
 void stop(){running=false;generation++;control=null;auth=null;synchronized(sockets){for(SSLSocket s:sockets)try{s.close();}catch(Exception ignored){}sockets.clear();}MediaCodec v=video,a=audio;video=null;audio=null;for(MediaCodec d:new MediaCodec[]{v,a})if(d!=null)try{d.stop();d.release();}catch(Exception ignored){}if(track!=null){try{track.stop();track.release();}catch(Exception ignored){}track=null;}}
 void openFiles(){boolean resume=running;String credential=auth;stop();auth=credential;transfer=new MediaTransfer(this,()->{transfer=null;if(resume){new Thread(()->{try{String id=session();runOnUiThread(()->show(id));}catch(Exception e){runOnUiThread(()->{auth=null;login();status.setText("重新连接失败："+message(e));});}},"resume-after-files").start();}else{auth=null;login();}});}
 public void onActivityResult(int request,int code,android.content.Intent data){super.onActivityResult(request,code,data);if(transfer!=null)transfer.result(request,code,data);}
 // API33+ is registered with the platform dispatcher above; this fallback serves API30-32.
 @android.annotation.SuppressLint("GestureBackNavigation")
 public void onBackPressed(){handleBack();}
 void handleBack(){if(transfer!=null){transfer.back();return;}if(running)input.execute(()->key(4));else finish();}
 protected void onResume(){super.onResume();if(updater!=null)updater.resumeInstall();}
 protected void onDestroy(){if(transfer!=null)transfer.close();stop();input.shutdownNow();statsThread.quitSafely();super.onDestroy();}
